"""Extract function source verbatim from the pinned MIT notebook, with explicit edits."""
import ast
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
nb = json.loads((ROOT / 'upstream/notebook/FinalProject.ipynb').read_text(encoding='utf-8'))
parts = ['# Adapted from Kiya-rb/vision-based-adas-dashboard (MIT).',
         '# Commit 58e6f31f5e4cc8c7b1c838920d9da454e2c11627. See upstream/LICENSE.',
         '# Generated by tools/extract_upstream.py; no notebook plotting/setup is executed.',
         'import cv2 as cv\nimport numpy as np\nfrom sklearn.cluster import DBSCAN\nfrom sklearn.preprocessing import StandardScaler\n']
for cell in nb['cells']:
    if cell['cell_type'] != 'code':
        continue
    source = ''.join(cell['source'])
    for node in ast.parse(source).body:
        if isinstance(node, ast.FunctionDef):
            text = ast.get_source_segment(source, node)
            # NumPy boxes from real inference replace Torch tensors. No Torch on board.
            text = text.replace('.xyxy[0].int().tolist()', '.xyxy[0].astype(int).tolist()')
            if node.name == 'apply_clahe':
                # VideoCapture supplies BGR; subsequent upstream masking also uses BGR.
                text = text.replace('cv.COLOR_RGB2LAB', 'cv.COLOR_BGR2LAB')
                text = text.replace('cv.COLOR_LAB2RGB', 'cv.COLOR_LAB2BGR')
            if node.name in ('merging_lines_dbscan', 'merging_lines_video'):
                # Cluster indices address filtered valid_lines, not the raw Hough array.
                text = text.replace("valid_lines.append({'slope':", "valid_lines.append({'segment': line.copy(), 'slope':")
                text = text.replace('lines[i][0]', "valid_lines[i]['segment'][0]")
            if node.name == 'analyze_traffic_and_alarms':
                text = text.replace('    annotated_image = lane_image.copy()',
                                    '    yolo_model.events = []\n    annotated_image = lane_image.copy()')
                text = text.replace('            # 6. UI Rendering (HUD Overlay)',
                    "            yolo_model.events.append({'box': [x1, y1, x2, y2], 'class': class_name,\n"
                    "                'score': float(box.conf[0]), 'lane': label, 'fcw': label.startswith('ALARM:')})\n"
                    '            # 6. UI Rendering (HUD Overlay)')
            parts.append(text)
(ROOT / 'adas/upstream_lanes.py').write_text('\n\n'.join(parts) + '\n', encoding='utf-8')
print('Extracted', sum('def ' in x for x in parts), 'functions')
